mapper.update:
UPDATE ASYNC_TASK
SET STATUS=#{status}, RESULT_JSON=#{resultJson}, ERROR_TEXT=#{errorText}, UPDATED_AT=#{updatedAt}, FINISHED_AT=#{finishedAt}, LEASE_OWNER_ID=#{leaseOwnerId}, LEASE_EXPIRES_AT=#{leaseExpiresAt}
WHERE DELETED=0 AND (TASK_ID=#{taskId})

mapper.select:
SELECT KIND, STATUS, LEASE_OWNER_ID, COUNT(*) AS OPEN_TASKS FROM ASYNC_TASK
WHERE DELETED=0 AND (TENANT_ID=#{tenant} AND KIND IN #{kind}
AND STATUS IN #{status}) GROUP BY KIND, STATUS, LEASE_OWNER_ID

SELECT TASK_ID FROM ASYNC_TASK WHERE DELETED=0 AND (KIND IN #{kind}
AND KIND NOT LIKE 'agent.readonly.%'
AND ((STATUS='PENDING' AND CREATED_AT < #{pending})
  OR (STATUS='RUNNING' AND ((LEASE_EXPIRES_AT IS NOT NULL AND LEASE_EXPIRES_AT < #{running})
  OR (LEASE_EXPIRES_AT IS NULL AND UPDATED_AT < #{running}))))) ORDER BY CREATED_AT LIMIT #{limit}
